2886:             for revoke in [false, true] {
2887:                 let (dir, settings, call) = scoped_audio_setup(wrapped);
2888:                 let (owner, context) = audio_scope(crate::memory_scope::ScopeSnapshot::room());
2889:                 let lease = owner.lease();
2890:                 let offer = audio_offer(context.clone());
2891:                 let served = scoped_reply(
2892:                     &dir.join(CALL_SOCKET),
2893:                     owner.clone(),
2894:                     revoke,
2895:                     json!({"ok":true,"result":{
2896:                         "next":"Say one short confirmation.","requested_audio":&offer,
2897:                     }}),
2898:                 );
