2901:                     assert_eq!(answer.told, unavailable());
2902:                     assert!(answer.requested_audio.is_none());
2903:                     assert!(!lease.is_current());
2904:                 } else {
2905:                     assert_eq!(answer.told, json!({"next":"Say one short confirmation."}));
2906:                     assert_eq!(answer.requested_audio, Some(offer));
2907:                     assert!(lease.is_current());
