2909:                 assert_eq!(
2910:                     served.join().unwrap(),
2911:                     json!({"op":"call","name":"play_relaxing_music","args":{},
2912:                         "requested_audio_context":context}),
2913:                     "translation must retain the original call id, request and time bound"
2914:                 );
2915:                 std::fs::remove_dir_all(dir).unwrap();
2916:             }
2917:         }
