2921:     fn scoped_audio_rejects_revocation_and_mixed_request_keys_before_dispatch() {
2922:         for wrapped in [false, true] {
2923:             let (dir, settings, call) = scoped_audio_setup(wrapped);
2924:             let listener = UnixListener::bind(dir.join(CALL_SOCKET)).unwrap();
2925:             listener.set_nonblocking(true).unwrap();
2926:             for change in ["revoked", "request", "session", "worker"] {
2927:                 let (owner, mut context) = audio_scope(crate::memory_scope::ScopeSnapshot::room());
2928:                 let lease = owner.lease();
2929:                 match change {
2930:                     "revoked" => owner.revoke(),
2931:                     "request" => context.request += 1,
2932:                     "session" => context.provider_session += 1,
2933:                     "worker" => context.worker_boot = "b".repeat(32),
2934:                     _ => unreachable!(),
2935:                 }
2936:                 let (whom, answer, answered) = run_spoken_call_scoped(
2937:                     &settings,
2938:                     &route(&settings, &call.name),
2939:                     &call,
2940:                     lease.key().request,
2941:                     true,
2942:                     Some(&context),
2943:                     &lease,
2944:                 );
2945:                 assert_eq!(whom, "nobody", "{change}");
2946:                 assert!(!answered, "{change}");
2947:                 assert_eq!(answer.told, unavailable(), "{change}");
2948:                 assert!(answer.requested_audio.is_none(), "{change}");
2949:                 assert_eq!(
